arguments.command:
mkdir -p /root/output && python3 - <<'PY'
import openpyxl
from openpyxl.utils import get_column_letter

path='/root/data/workbook.xlsx'
wb=openpyxl.load_workbook(path)
print('Sheets:', wb.sheetnames)
ws_task=wb['Task']
ws_data=wb['Data']

print('\n=== Task sheet: series codes in column D ===')
blocks=[(12,17),(19,24),(26,31)]
for r0,r1 in blocks:
    print(f'Rows {r0}-{r1}:')
    for r in range(r0,r1+1):
        v=ws_task[f'D{r}'].value
        print(f'  D{r}: {v!r}')

print('\n=== Task sheet: year headers row 10, columns H-L ===')
for c in range(8,13):
    addr=f'{get_column_letter(c)}10'
    print(f'  {addr}: {ws_task[addr].value!r}')

print('\n=== Task sheet: yellow input blocks H12:L31 current contents (only non-empty shown) ===')
for r0,r1 in blocks:
    for r in range(r0,r1+1):
        row_vals=[]
        for c in range(8,13):
            addr=f'{get_column_letter(c)}{r}'
            row_vals.append((addr, ws_task[addr].value))
        non_empty=[(a,v) for a,v in row_vals if v not in (None,'')]
        if non_empty:
            print(f'  Row {r} non-empty:', [(a,repr(v)) for a,v in non_empty])

print('\n=== Task sheet: labels around rows 35-47 and row 50 (cols B-G) ===')
for r in list(range(35,48))+[50]:
    vals={}
    for col in ['B','C','D','E','F','G']:
        vals[col]=ws_task[f'{col}{r}'].value
    print(f'Row {r}:', vals)

print('\n=== Data sheet: inspect rows 21-38, cols A-N ===')
min_row,max_row=21,38
min_col,max_col=1,14
for r in range(min_row,max_row+1):
    row=[]
    for c in range(min_col,max_col+1):
        v=ws_data.cell(r,c).value
        row.append(v)
    while row and row[-1] is None:
        row.pop()
    print(f'{r}:', row)

print('\n=== Heuristic: detect year header rows ===')
import re
for r in range(21,39):
    years=[]
    for c in range(1,40):
        v=ws_data.cell(r,c).value
        if isinstance(v,int) and 1900<=v<=2100:
            years.append((c,v))
        elif isinstance(v,str) and re.fullmatch(r'20\d{2}', v.strip()):
            years.append((c,int(v.strip())))
    if len(years)>=3:
        print('Row',r,'years:', years[:10])

print('\n=== Heuristic: detect series-code column (strings) ===')
for c in range(1,15):
    vals=[ws_data.cell(r,c).value for r in range(21,39)]
    str_vals=[v for v in vals if isinstance(v,str) and v.strip()]
    if len(str_vals)>=10:
        print('Col',get_column_letter(c),'string count',len(str_vals),'sample',str_vals[:5])
PY

